-- Model: lnk_timesheet_match__timesheet_hkey_curr
-- Description: Current active relationship for LNK_TIMESHEET_MATCH using ROW_NUMBER()
-- Generated by: bv pipeline generate transform
-- Link Type: RELATIONSHIP_BASED_LINK

WITH RANKED_RELATIONSHIPS AS (
SELECT
    l.LNK_TIMESHEET_MATCH_HKEY AS LNK_TIMESHEET_MATCH_HKEY,
    l.TIMESHEET_HKEY AS TIMESHEET_HKEY,
    l.MATCH_HKEY AS MATCH_HKEY,

    -- TODO: use generated tag instead of well-known name _CURRENT_ACTIVE_TIMESTAMP
    ls._CURRENT_ACTIVE_TIMESTAMP AS _CURRENT_RELATIONSHIP_TIMESTAMP, -- was ls.LOAD_DATE

    ROW_NUMBER() OVER (
        PARTITION BY l.TIMESHEET_HKEY -- parent hub hk
        ORDER BY ls._CURRENT_ACTIVE_TIMESTAMP DESC -- TODO: as above. Was ls.LOAD_DATE
    ) AS row_num

FROM {{ source('eli_dv_rv', 'lnk_timesheet_match') }} l
INNER JOIN {{ ref('lks_erc_timesheet_match_curr') }} ls
    ON l.LNK_TIMESHEET_MATCH_HKEY = ls.LNK_TIMESHEET_MATCH_HKEY
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RELATIONSHIPS
WHERE row_num = 1
